-- ───────────────────────── part 2 — raw SQL (ADR-002)

ALTER TABLE projects
  ADD CONSTRAINT projects_budget_chk CHECK (budget IS NULL OR budget >= 0),
  ADD CONSTRAINT projects_currency_chk CHECK (currency ~ '^[A-Z]{3}$');

ALTER TABLE tasks
  ADD CONSTRAINT tasks_planned_cost_chk CHECK (planned_cost >= 0),
  ADD CONSTRAINT tasks_actual_cost_chk CHECK (actual_cost >= 0),
  ADD CONSTRAINT tasks_bar_color_chk CHECK (bar_color IS NULL OR bar_color ~ '^#[0-9A-Fa-f]{6}$');

ALTER TABLE project_labels
  ADD CONSTRAINT project_labels_color_chk CHECK (color ~ '^#[0-9A-Fa-f]{6}$'),
  ADD CONSTRAINT project_labels_name_chk CHECK (length(btrim(name)) > 0);

ALTER TABLE custom_fields
  ADD CONSTRAINT custom_fields_options_chk CHECK (jsonb_typeof(options) = 'array');

ALTER TABLE time_entries
  ADD CONSTRAINT time_entries_minutes_chk CHECK (minutes BETWEEN 1 AND 1440);

-- 32 KB cap on one preference value (the API checks it first, VIEW_PREF_TOO_LARGE).
ALTER TABLE user_view_prefs
  ADD CONSTRAINT user_view_prefs_value_size_chk CHECK (octet_length(value::text) <= 32768);

-- (user, project, key) is unique; NULL project = a global preference of the user.
CREATE UNIQUE INDEX user_view_prefs_project_uq
  ON user_view_prefs (user_id, project_id, key)
  WHERE project_id IS NOT NULL;
CREATE UNIQUE INDEX user_view_prefs_global_uq
  ON user_view_prefs (user_id, key)
  WHERE project_id IS NULL;

-- The daily job: live, open tasks whose deadline passed and was not notified yet.
CREATE INDEX tasks_deadline_reminder_idx
  ON tasks (deadline)
  WHERE archived_at IS NULL AND deadline IS NOT NULL AND deadline_notified_at IS NULL AND status <> 'DONE';

-- Communication hub "I'm mentioned".
CREATE INDEX task_comments_mentions_gin
  ON task_comments USING GIN (mentions);

-- Template list and the project list (templates are hidden from it).
CREATE INDEX projects_templates_idx
  ON projects (created_at)
  WHERE is_template;
